/// <summary>
/// MET Follow trans item gst group on modified
/// </summary>
/// <param name="sender"> Get form data scontrol object</param>
/// <param name="e">Get form control event args</param>
[FormControlEventHandler(formControlStr(TAMRebatePosting, METFollowTransItemGSTGroup), FormControlEventType::Modified),
 SuppressBPWarningAttribute("BPParameterNotUsed", "@MET:BPParameterNotUsedMessage")]
public static void METFollowTransItemGSTGroup_OnModified(FormControl sender, FormControlEventArgs e)
{
    FormCheckBoxControl  METFollowTransItemGSTGroup = sender as FormCheckBoxControl;

    FormRun formRun = METFollowTransItemGSTGroup.formRun();
    FormStringControl frmCtl = formRun.design().controlName(formControlStr(TAMRebatePosting, Rebate_TaxItemGroup));

    if (METFollowTransItemGSTGroup.checked())
    {
        frmCtl.text('');
        frmCtl.enabled(false);
    }
    else
    {
        frmCtl.enabled(true);
    }   
}
